// AUTO-DISCOVERY: Detect brands from MSC-ALGO output files.
// Scans Output/*/ for *_Growth_Opportunities.csv
// No manual brand input needed — synced with MSC-ALGO.
const fs = require('fs');
const path = require('path');

const projectRoot = process.env.PROJECT_ROOT || 'c:/Users/Paweł/Documents/GitHub/Money Printing Machine';
const outputDir = path.join(projectRoot, 'Output');

const brands = [];
try {
  const dirs = fs.readdirSync(outputDir, { withFileTypes: true });
  for (const dir of dirs) {
    if (!dir.isDirectory()) continue;
    const brandName = dir.name;
    const csvPath = path.join(outputDir, brandName, `${brandName}_Growth_Opportunities.csv`);
    if (fs.existsSync(csvPath)) {
      brands.push({ json: { brand: brandName } });
    }
  }
} catch (e) {
  throw new Error(`Cannot scan Output directory: ${e.message}`);
}

if (brands.length === 0) {
  throw new Error('No brands found. Run MSC-ALGO first to generate Growth_Opportunities.csv files.');
}

return brands;

// UNIVERSAL: Resolve all paths from brand name (no hardcoded values)
const fs = require('fs');
const path = require('path');

const brand = $input.first().json.brand;
if (!brand) throw new Error('No brand specified. Set Brand node must provide { brand: "Name" }');

// Auto-detect project root from known workflow location
// Works on any machine: Render, local Windows, CI
const projectRoot = process.env.PROJECT_ROOT || 'c:/Users/Paweł/Documents/GitHub/Money Printing Machine';

// Universal path conventions:
// Input:  Input/{Brand}/{brand_lower}_product_feed.xml
// Output: Output/{Brand}/{Brand}_Growth_Opportunities.csv
// Cache:  cache/enrichment/{brand_lower}/
const csvPath = path.join(projectRoot, 'Output', brand, `${brand}_Growth_Opportunities.csv`);
const feedPath = path.join(projectRoot, 'Input', brand, `${brand.toLowerCase()}_product_feed.xml`);
const cacheDir = path.join(projectRoot, 'cache', 'enrichment', brand.toLowerCase());
const configPath = path.join(projectRoot, 'business_logic.json');

// Validate CSV exists
if (!fs.existsSync(csvPath)) {
  throw new Error(`MSC-ALGO output not found: ${csvPath}. Run MSC-ALGO for ${brand} first.`);
}

// Load business_logic.json
let config = {};
try {
  config = JSON.parse(fs.readFileSync(configPath, 'utf-8'));
} catch (e) { /* optional */ }

// Ensure brand-specific cache dir exists
if (!fs.existsSync(cacheDir)) {
  fs.mkdirSync(cacheDir, { recursive: true });
}

return [{
  json: {
    brand,
    projectRoot,
    csvPath,
    feedPath: fs.existsSync(feedPath) ? feedPath : '',
    cacheDir,
    config: config[brand] || config[brand.toLowerCase()] || {},
    timestamp: new Date().toISOString()
  }
}];

// Read Growth_Opportunities.csv and emit rows as items
const fs = require('fs');
const config = $input.first().json;

if (!fs.existsSync(config.csvPath)) {
  throw new Error(`CSV not found: ${config.csvPath}`);
}

const raw = fs.readFileSync(config.csvPath, 'utf-8');
const lines = raw.split('\n').filter(l => l.trim());
const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, ''));

const items = [];
for (let i = 1; i < lines.length; i++) {
  // Simple CSV parse (handles quoted fields)
  const values = [];
  let current = '';
  let inQuotes = false;
  for (const ch of lines[i]) {
    if (ch === '"') { inQuotes = !inQuotes; }
    else if (ch === ',' && !inQuotes) { values.push(current.trim()); current = ''; }
    else { current += ch; }
  }
  values.push(current.trim());

  const row = {};
  headers.forEach((h, idx) => {
    row[h] = values[idx] || '';
  });

  // Carry config forward
  row._brand = config.brand;
  row._projectRoot = config.projectRoot;
  row._cacheDir = config.cacheDir;
  row._feedPath = config.feedPath;

  items.push({ json: row });
}

return items;

// Check if product has fresh cache entry (< 7 days old)
const fs = require('fs');
const crypto = require('crypto');

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  const productId = d.feed_id || '';
  const price = parseFloat(d.feed_price_numeric) || 0;
  const category = d.feed_category || '';

  // Hash: product_id + price + category
  const raw = `${productId}|${price.toFixed(2)}|${category}`;
  const key = crypto.createHash('sha256').update(raw).digest('hex').substring(0, 16);
  const cachePath = `${d._cacheDir}/${key}.json`;

  let cacheHit = false;
  let cachedData = null;

  try {
    if (fs.existsSync(cachePath)) {
      const entry = JSON.parse(fs.readFileSync(cachePath, 'utf-8'));
      const harvestDate = new Date(entry.harvest_date);
      const age = (Date.now() - harvestDate.getTime()) / (1000 * 60 * 60 * 24);
      if (age < 7) {
        cacheHit = true;
        cachedData = entry.data;
      }
    }
  } catch (e) {
    // Cache miss on error
  }

  results.push({
    json: {
      ...d,
      _cacheKey: key,
      _cachePath: cachePath,
      _cacheHit: cacheHit,
      ...(cachedData || {})
    }
  });
}

return results;

// Cached products already have enrichment data — pass through
const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    _source: 'cache'
  }
}));

