// Parse Claude response and merge enrichment data into product row
const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;

  // Claude response: content[0].text
  let analysisText = d.content?.[0]?.text || '';

  // Parse JSON from response
  let analysis = {};
  try {
    // Clean markdown fences
    analysisText = analysisText.replace(/```json/g, '').replace(/```/g, '').trim();
    analysis = JSON.parse(analysisText);
  } catch (e) {
    // Fallback: extract first JSON object
    try {
      const start = analysisText.indexOf('{');
      const end = analysisText.lastIndexOf('}');
      if (start !== -1 && end > start) {
        analysis = JSON.parse(analysisText.substring(start, end + 1));
      }
    } catch (e2) {
      // Give up — empty analysis
    }
  }

  // Quality gate: at least 3 fields filled
  const filled = Object.values(analysis).filter(v => v && v.length > 0).length;
  const qualityOk = filled >= 3;

  results.push({
    json: {
      ...d,
      persona_name: analysis.persona_name || '',
      persona_dream: analysis.persona_dream || '',
      persona_fear: analysis.persona_fear || '',
      persona_awareness: analysis.persona_awareness || '',
      tech_translator: analysis.tech_translator || '',
      social_proof_quote: analysis.social_proof_quote || '',
      competitive_edge: analysis.competitive_edge || '',
      visual_hook_suggestion: analysis.visual_hook_suggestion || '',
      buying_objections: analysis.buying_objections || '',
      harvest_date: new Date().toISOString().split('T')[0],
      _quality_ok: qualityOk,
      _quality_filled: filled,
      _source: 'fresh'
    }
  });
}

return results;

// Write enrichment result to cache file
const fs = require('fs');

const items = $input.all();

for (const item of items) {
  const d = item.json;
  if (d._cacheHit) continue; // Don't re-cache cached items

  const cacheEntry = {
    product_id: d.feed_id,
    harvest_date: new Date().toISOString(),
    data: {
      persona_name: d.persona_name || '',
      persona_dream: d.persona_dream || '',
      persona_fear: d.persona_fear || '',
      persona_awareness: d.persona_awareness || '',
      tech_translator: d.tech_translator || '',
      social_proof_quote: d.social_proof_quote || '',
      competitive_edge: d.competitive_edge || '',
      visual_hook_suggestion: d.visual_hook_suggestion || '',
      buying_objections: d.buying_objections || '',
      harvest_date: d.harvest_date || ''
    }
  };

  try {
    fs.writeFileSync(d._cachePath, JSON.stringify(cacheEntry, null, 2), 'utf-8');
  } catch (e) {
    // Cache write failure is non-fatal
  }
}

return items;

// Write final Enriched_Products.csv
const fs = require('fs');
const path = require('path');

const items = $input.all();
if (items.length === 0) {
  return [{ json: { status: 'no_items', message: 'No products to write' } }];
}

// Define output columns (34 quant + 10 qual)
const skipCols = ['_brand', '_projectRoot', '_cacheDir', '_feedPath', '_cacheKey', '_cachePath', '_cacheHit', '_source', '_quality_ok', '_quality_filled', '_product_reviews', '_category_insights'];
const allKeys = Object.keys(items[0].json).filter(k => !skipCols.includes(k));

// Build CSV
const header = allKeys.join(',');
const rows = items.map(item => {
  return allKeys.map(k => {
    let v = item.json[k] || '';
    v = String(v).replace(/"/g, '""');
    return `"${v}"`;
  }).join(',');
});

const csv = [header, ...rows].join('\n');

// Get output path from first item
const brand = items[0].json._brand || 'Unknown';
const projectRoot = items[0].json._projectRoot || '.';
const outputPath = path.join(projectRoot, 'Output', brand, `${brand}_Enriched_Products.csv`);

fs.writeFileSync(outputPath, csv, 'utf-8');

const cached = items.filter(i => i.json._source === 'cache').length;
const fresh = items.filter(i => i.json._source !== 'cache').length;

return [{
  json: {
    status: 'success',
    outputPath,
    totalProducts: items.length,
    fromCache: cached,
    freshlyEnriched: fresh,
    columns: allKeys.length,
    timestamp: new Date().toISOString()
  }
}];

// Log error details
const error = $input.first().json;
return [{
  json: {
    status: 'error',
    workflow: error.workflow?.name || 'Enrichment Pipeline',
    node: error.execution?.error?.node?.name || 'unknown',
    message: error.execution?.error?.message || 'Unknown error',
    timestamp: new Date().toISOString()
  }
}];
